cd /tmp 2>/dev/null; curl -s --max-time 20 "https://wttr.in/?format=j1" -o w.json && node -e "
const d=require('./w.json');const w=d.weather[0];
console.log('日期',w.date,'最高',w.maxtempC+'°C','最低',w.mintempC+'°C','日照小时',w.sunHour,'UV',w.uvIndex);
console.log('日出',w.astronomy[0].sunrise,'日落',w.astronomy[0].sunset,'月相',w.astronomy[0].moon_phase);
for(const h of w.hourly){console.log(h.time.padStart(4,'0'),h.tempC+'°C','体感'+h.FeelsLikeC+'°C',h.weatherDesc[0].value,'降雨概率'+h.chanceofrain+'%','湿度'+h.humidity+'%',h.windspeedKmph+'km/h',h.winddir16Point);}
" 2>&1 | head -30

